    "scores": {
      "privacy": 8,
      "security": 8,
      "performance": 7,
      "governance": 8,
      "reliability": 9,
      "cost": 9
    },
    "pins": [
      {
        "name": "exec_in",
        "friendlyName": "Input",
        "description": "Execution trigger that begins the ROC evaluation",
        "pinType": "Input",
        "dataType": "Execution",
        "valueType": "Normal",
        "index": 1
      },
      {
        "name": "database",
        "friendlyName": "Database",
        "description": "Database connection containing the predicted probabilities and the true labels",
        "pinType": "Input",
        "dataType": "Struct",
        "valueType": "Normal",
        "schema": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"title\":\"NodeDBConnection\",\"type\":\"object\",\"properties\":{\"cache_key\":{\"type\":\"string\"}},\"required\":[\"cache_key\"]}",
        "index": 2,
        "options": {
          "enforceSchema": true
        }
      },
      {
        "name": "probabilities_col",
        "friendlyName": "Probabilities Column",
        "description": "Column holding P(positive class) for each row, between 0 and 1 — the probability of the class named in Positive Label, NOT the probability of whichever class was predicted. No node writes this column for you: Predict in Database mode writes the predicted class only, and `confidence` is a field on the struct its Vector mode returns for one row, so build the column by looping rows through Vector mode. Convert as you go, because `confidence` is the winning class's probability: use it directly where the prediction is the positive class, and 1 - confidence elsewhere. A raw decision value or an uncalibrated score produces a meaningless curve.",
        "pinType": "Input",
        "dataType": "String",
        "valueType": "Normal",
        "defaultValue": "probability",
        "index": 3
      },
      {
        "name": "actuals_col",
        "friendlyName": "Actuals Column",
        "description": "Column holding the true binary label of each sample",
        "pinType": "Input",
        "dataType": "String",
        "valueType": "Normal",
        "defaultValue": "target",
        "index": 4
      },
      {
        "name": "positive_label",
        "friendlyName": "Positive Label",
        "description": "Value of the actuals column that counts as the positive class. Strings are compared literally, numbers numerically; booleans are always taken as-is.",
        "pinType": "Input",
        "dataType": "String",
        "valueType": "Normal",
        "defaultValue": "1",
        "index": 5
      },
      {
        "name": "exec_out",
        "friendlyName": "Done",
        "description": "Activated once the ROC evaluation completes",
        "pinType": "Output",
        "dataType": "Execution",
        "valueType": "Normal",
        "index": 1
      },
      {
        "name": "auc",
        "friendlyName": "AUC",
        "description": "Area under the ROC curve (0.5 = random, 1.0 = perfect)",
        "pinType": "Output",
        "dataType": "Float",
        "valueType": "Normal",
        "index": 2
      },
      {
        "name": "log_loss",
        "friendlyName": "Log Loss",
        "description": "Mean binary cross-entropy of the predicted probabilities (lower is better)",
        "pinType": "Output",
        "dataType": "Float",
        "valueType": "Normal",
        "index": 3
      },
      {
        "name": "result",
        "friendlyName": "Result",
        "description": "AUC, log loss and the ROC curve points ordered by ascending false positive rate",
        "pinType": "Output",
        "dataType": "Struct",
        "valueType": "Normal",
        "schema": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"title\":\"RocAucResult\",\"description\":\"ROC-AUC, log loss and the full ROC curve of a binary classifier\",\"type\":\"object\",\"properties\":{\"auc\":{\"description\":\"Area under the ROC curve. 0.5 is a coin flip, 1.0 is a perfect ranking.\",\"type\":\"number\",\"format\":\"double\"},\"log_loss\":{\"description\":\"Mean binary cross-entropy of the predicted probabilities. Lower is better.\",\"type\":\"number\",\"format\":\"double\"},\"curve\":{\"description\":\"Curve points ordered by ascending false positive rate, ready to be charted\",\"type\":\"array\",\"items\":{\"$ref\":\"#/$defs/RocPoint\"}},\"n_samples\":{\"description\":\"Number of samples evaluated\",\"type\":\"integer\",\"format\":\"uint\",\"minimum\":0},\"n_positive\":{\"description\":\"Number of samples whose true label is positive\",\"type\":\"integer\",\"format\":\"uint\",\"minimum\":0},\"n_negative\":{\"description\":\"Number of samples whose true label is negative\",\"type\":\"integer\",\"format\":\"uint\",\"minimum\":0}},\"required\":[\"auc\",\"log_loss\",\"curve\",\"n_samples\",\"n_positive\",\"n_negative\"],\"$defs\":{\"RocPoint\":{\"description\":\"A single point of the Receiver-Operating-Characteristic curve\",\"type\":\"object\",\"properties\":{\"threshold\":{\"description\":\"Probability threshold this point was measured at. `null` for the closing (0, 0) endpoint,\\nwhich corresponds to classifying everything as negative.\",\"type\":[\"number\",\"null\"],\"format\":\"double\"},\"false_positive_rate\":{\"description\":\"False positive rate at this threshold, the x axis of the curve\",\"type\":\"number\",\"format\":\"double\"},\"true_positive_rate\":{\"description\":\"True positive rate (recall) at this threshold, the y axis of the curve\",\"type\":\"number\",\"format\":\"double\"}},\"required\":[\"false_positive_rate\",\"true_positive_rate\"]}}}",
        "index": 4
      }
    ],
    "inputCount": 5,
    "outputCount": 4,
