        "schema": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"title\":\"NodeMLModel\",\"description\":\"Unified Machine Learning Model Type on Board Level\",\"type\":\"object\",\"properties\":{\"model_ref\":{\"type\":\"string\"}},\"required\":[\"model_ref\"]}",
        "index": 2,
