        "pinType": "Output",
        "dataType": "Struct",
        "valueType": "Normal",
        "schema": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"title\":\"OrdinalLevels\",\"description\":\"The ordered levels of an ordinal target.\",\"type\":\"object\",\"properties\":{\"labels\":{\"description\":\"Level labels from lowest to highest; the index is the rank the model was trained on.\",\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"ordering\":{\"description\":\"Where the ordering came from.\",\"$ref\":\"#/$defs/OrdinalOrdering\"}},\"required\":[\"labels\",\"ordering\"],\"$defs\":{\"OrdinalOrdering\":{\"description\":\"How the level order of an ordinal target column was established.\",\"oneOf\":[{\"description\":\"Every distinct label parsed as a number, so the order is the numeric one.\",\"type\":\"string\",\"const\":\"Numeric\"},{\"description\":\"The caller supplied the order explicitly.\",\"type\":\"string\",\"const\":\"Explicit\"}]}}}",
        "index": 3
