        "schema": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"title\":\"GraphSearchHit\",\"description\":\"Search hit from Microsoft Graph Search API\\nBased on https://learn.microsoft.com/en-us/graph/api/resources/searchhit\",\"type\":\"object\",\"properties\":{\"hit_id\":{\"description\":\"The internal identifier for the item (format varies by entity type)\",\"type\":\"string\"},\"rank\":{\"description\":\"The rank or order of the result\",\"type\":[\"integer\",\"null\"],\"format\":\"int32\"},\"summary\":{\"description\":\"A summary of the result, if available\",\"type\":[\"string\",\"null\"]},\"result_template_id\":{\"description\":\"ID of the result template used to render the search result\",\"type\":[\"string\",\"null\"]},\"resource\":{\"description\":\"The underlying resource data\",\"$ref\":\"#/$defs/GraphSearchResource\"}},\"required\":[\"hit_id\",\"resource\"],\"$defs\":{\"GraphSearchResource\":{\"description\":\"Resource data from a search hit\\nCombines properties from driveItem, message, event, site, list, listItem, etc.\",\"type\":\"object\",\"properties\":{\"@odata.type\":{\"description\":\"The OData type of the resource (e.g., \\\"#microsoft.graph.driveItem\\\")\",\"type\":[\"string\",\"null\"]},\"id\":{\"description\":\"Unique identifier for the resource\",\"type\":\"string\"},\"name\":{\"description\":\"Display name (for files, sites, lists)\",\"type\":[\"string\",\"null\"]},\"display_name\":{\"description\":\"Display name alternative\",\"type\":[\"string\",\"null\"]},\"subject\":{\"description\":\"Subject (for emails, events)\",\"type\":[\"string\",\"null\"]},\"web_url\":{\"description\":\"URL to access the resource in a browser\",\"type\":[\"string\",\"null\"]},\"web_link\":{\"description\":\"Alternative web link (for emails)\",\"type\":[\"string\",\"null\"]},\"created_date_time\":{\"description\":\"Date and time the item was created (ISO 8601)\",\"type\":[\"string\",\"null\"]},\"last_modified_date_time\":{\"description\":\"Date and time the item was last modified (ISO 8601)\",\"type\":[\"string\",\"null\"]},\"size\":{\"description\":\"Size in bytes (for files)\",\"type\":[\"integer\",\"null\"],\"format\":\"int64\"},\"parent_reference\":{\"description\":\"Parent reference information\",\"anyOf\":[{\"$ref\":\"#/$defs/GraphParentReference\"},{\"type\":\"null\"}]},\"file\":{\"description\":\"File-specific metadata (present if item is a file)\",\"anyOf\":[{\"$ref\":\"#/$defs/GraphFileFacet\"},{\"type\":\"null\"}]},\"folder\":{\"description\":\"Folder-specific metadata (present if item is a folder)\",\"anyOf\":[{\"$ref\":\"#/$defs/GraphFolderFacet\"},{\"type\":\"null\"}]},\"sender\":{\"description\":\"Email sender information\",\"anyOf\":[{\"$ref\":\"#/$defs/GraphRecipient\"},{\"type\":\"null\"}]},\"from\":{\"description\":\"Email from information\",\"anyOf\":[{\"$ref\":\"#/$defs/GraphRecipient\"},{\"type\":\"null\"}]},\"has_attachments\":{\"description\":\"Whether the email has attachments\",\"type\":[\"boolean\",\"null\"]},\"is_read\":{\"description\":\"Whether the email is read\",\"type\":[\"boolean\",\"null\"]},\"body_preview\":{\"description\":\"Body preview (for emails)\",\"type\":[\"string\",\"null\"]},\"received_date_time\":{\"description\":\"Date and time email was received\",\"type\":[\"string\",\"null\"]},\"sent_date_time\":{\"description\":\"Date and time email was sent\",\"type\":[\"string\",\"null\"]},\"start\":{\"description\":\"Event start time\",\"anyOf\":[{\"$ref\":\"#/$defs/GraphDateTimeTimeZone\"},{\"type\":\"null\"}]},\"end\":{\"description\":\"Event end time\",\"anyOf\":[{\"$ref\":\"#/$defs/GraphDateTimeTimeZone\"},{\"type\":\"null\"}]},\"location\":{\"description\":\"Event location\",\"anyOf\":[{\"$ref\":\"#/$defs/GraphLocation\"},{\"type\":\"null\"}]},\"organizer\":{\"description\":\"Event organizer\",\"anyOf\":[{\"$ref\":\"#/$defs/GraphRecipient\"},{\"type\":\"null\"}]}},\"required\":[\"id\"]},\"GraphParentReference\":{\"description\":\"Parent reference for drive items\",\"type\":\"object\",\"properties\":{\"id\":{\"type\":[\"string\",\"null\"]},\"name\":{\"type\":[\"string\",\"null\"]},\"path\":{\"type\":[\"string\",\"null\"]},\"drive_id\":{\"type\":[\"string\",\"null\"]},\"site_id\":{\"type\":[\"string\",\"null\"]}}},\"GraphFileFacet\":{\"description\":\"File facet for drive items\",\"type\":\"object\",\"properties\":{\"mime_type\":{\"type\":[\"string\",\"null\"]}}},\"GraphFolderFacet\":{\"description\":\"Folder facet for drive items\",\"type\":\"object\",\"properties\":{\"child_count\":{\"type\":[\"integer\",\"null\"],\"format\":\"int32\"}}},\"GraphRecipient\":{\"description\":\"Recipient information (for emails, events)\",\"type\":\"object\",\"properties\":{\"email_address\":{\"anyOf\":[{\"$ref\":\"#/$defs/GraphEmailAddress\"},{\"type\":\"null\"}]}}},\"GraphEmailAddress\":{\"description\":\"Email address details\",\"type\":\"object\",\"properties\":{\"name\":{\"type\":[\"string\",\"null\"]},\"address\":{\"type\":[\"string\",\"null\"]}}},\"GraphDateTimeTimeZone\":{\"description\":\"Date/time with timezone (for events)\",\"type\":\"object\",\"properties\":{\"date_time\":{\"type\":[\"string\",\"null\"]},\"time_zone\":{\"type\":[\"string\",\"null\"]}}},\"GraphLocation\":{\"description\":\"Location information (for events)\",\"type\":\"object\",\"properties\":{\"display_name\":{\"type\":[\"string\",\"null\"]}}}}}",
