        "schema": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"title\":\"CalendarEvent\",\"description\":\"A single event/appointment shown on the interactive calendar.\",\"type\":\"object\",\"properties\":{\"id\":{\"description\":\"Stable unique id used to move/update/remove the item. Auto-generated when omitted.\",\"type\":[\"string\",\"null\"]},\"title\":{\"description\":\"Event title shown on the calendar.\",\"type\":\"string\"},\"start\":{\"description\":\"Start timestamp, ISO 8601 (e.g. \\\"2026-07-01T09:00:00Z\\\" or \\\"2026-07-01\\\").\",\"type\":\"string\",\"format\":\"date-time\"},\"end\":{\"description\":\"End timestamp, ISO 8601. Defaults to a short block when omitted.\",\"type\":[\"string\",\"null\"],\"format\":\"date-time\"},\"allDay\":{\"description\":\"Render as an all-day event (no time-of-day).\",\"type\":[\"boolean\",\"null\"]},\"color\":{\"description\":\"Accent color (CSS color or design token).\",\"type\":[\"string\",\"null\"]},\"description\":{\"description\":\"Optional longer description.\",\"type\":[\"string\",\"null\"]},\"location\":{\"description\":\"Optional location string.\",\"type\":[\"string\",\"null\"]},\"calendarId\":{\"description\":\"Grouping key (e.g. source calendar id).\",\"type\":[\"string\",\"null\"]},\"editable\":{\"description\":\"Whether this event can be moved/resized in the UI.\",\"type\":[\"boolean\",\"null\"]},\"link\":{\"description\":\"Optional link opened from the item's detail dialog. Relative paths\\n(e.g. \\\"/orders/42\\\") navigate inside the app; absolute URLs (https://\\u2026)\\nopen externally.\",\"type\":[\"string\",\"null\"]},\"metadata\":{\"description\":\"Key-value metadata echoed back on action events and shown in the\\nitem's detail dialog (e.g. ticket number, external ids).\",\"type\":[\"object\",\"null\"],\"additionalProperties\":true}},\"required\":[\"title\",\"start\"]}",
